CREATE TABLE auth_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "twoFactorEnabled" boolean DEFAULT false, "platformAdmin" boolean NOT NULL DEFAULT false);
CREATE TABLE auth_session (id text PRIMARY KEY, "userId" text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, token text NOT NULL UNIQUE, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text);
CREATE TABLE auth_account (id text PRIMARY KEY, "userId" text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, "accountId" text NOT NULL, "providerId" text NOT NULL, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId","accountId"));
CREATE TABLE auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE TABLE "twoFactor" (id text PRIMARY KEY, secret text NOT NULL, "backupCodes" text NOT NULL, "userId" text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, verified boolean DEFAULT true);
CREATE TABLE auth_rate_limit (id text PRIMARY KEY, key text UNIQUE NOT NULL, count integer NOT NULL, "lastRequest" bigint NOT NULL);
ALTER TABLE workspaces ADD COLUMN suspended boolean NOT NULL DEFAULT false, ADD COLUMN plan text NOT NULL DEFAULT 'free', ADD COLUMN settings jsonb NOT NULL DEFAULT '{}';
ALTER TABLE memberships DROP CONSTRAINT membership_role;
ALTER TABLE memberships ADD CONSTRAINT membership_role CHECK (role IN ('owner','admin','editor','viewer'));
CREATE TABLE workspace_access (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES users(id), role text NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE FUNCTION sync_workspace_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF TG_OP='DELETE' THEN DELETE FROM workspace_access WHERE workspace_id=OLD.workspace_id AND user_id=OLD.user_id; RETURN OLD; END IF; INSERT INTO workspace_access VALUES(NEW.workspace_id,NEW.user_id,NEW.role) ON CONFLICT(workspace_id,user_id) DO UPDATE SET role=EXCLUDED.role; RETURN NEW; END $$;
CREATE TRIGGER membership_access AFTER INSERT OR UPDATE OR DELETE ON memberships FOR EACH ROW EXECUTE FUNCTION sync_workspace_access();
CREATE FUNCTION authorize_workspace(actor text, workspace uuid) RETURNS TABLE(role text,suspended boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE previous text; BEGIN IF NOT EXISTS(SELECT 1 FROM workspace_access a WHERE a.user_id=actor AND a.workspace_id=workspace) THEN RETURN; END IF; previous:=current_setting('app.workspace_id',true); PERFORM set_config('app.workspace_id',workspace::text,true); RETURN QUERY SELECT a.role,w.suspended FROM workspace_access a JOIN workspaces w ON w.id=a.workspace_id WHERE a.user_id=actor AND a.workspace_id=workspace FOR UPDATE OF w; PERFORM set_config('app.workspace_id',coalesce(previous,''),true); END $$;
CREATE FUNCTION list_user_workspaces(actor text) RETURNS TABLE(id uuid,name text,role text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE item record; previous text; BEGIN previous:=current_setting('app.workspace_id',true); FOR item IN SELECT * FROM workspace_access WHERE user_id=actor LOOP PERFORM set_config('app.workspace_id',item.workspace_id::text,true); RETURN QUERY SELECT w.id,w.name,item.role FROM workspaces w WHERE w.id=item.workspace_id AND NOT w.suspended; END LOOP; PERFORM set_config('app.workspace_id',coalesce(previous,''),true); END $$;
CREATE FUNCTION create_user_workspace(actor text, workspace uuid, label text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM auth_user WHERE id=actor) THEN RAISE EXCEPTION 'Unknown user' USING ERRCODE='42501'; END IF; INSERT INTO users(id) VALUES(actor) ON CONFLICT DO NOTHING; PERFORM set_config('app.workspace_id',workspace::text,true); INSERT INTO workspaces(id,name) VALUES(workspace,label); INSERT INTO memberships(workspace_id,user_id,role) VALUES(workspace,actor,'owner'); END $$;
CREATE TABLE monitors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, type text NOT NULL CHECK(type IN ('http','keyword','ping','port','heartbeat','ssl','domain','dns','api')), target text NOT NULL, config jsonb NOT NULL DEFAULT '{}', interval_seconds integer NOT NULL DEFAULT 300 CHECK(interval_seconds>=30), state text NOT NULL DEFAULT 'unknown', paused boolean NOT NULL DEFAULT false, archived_at timestamptz, config_version integer NOT NULL DEFAULT 1, next_check_at timestamptz NOT NULL DEFAULT now(), lease_token uuid, lease_until timestamptz, lease_worker text, failure_count integer NOT NULL DEFAULT 0, success_count integer NOT NULL DEFAULT 0, heartbeat_hash text, heartbeat_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE check_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, monitor_id uuid NOT NULL, state text NOT NULL, duration_ms double precision, status_code integer, error_code text, region text NOT NULL, observed_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, FOREIGN KEY(workspace_id,monitor_id) REFERENCES monitors(workspace_id,id));
CREATE INDEX checks_monitor_time ON check_results(workspace_id,monitor_id,observed_at DESC);
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, monitor_id uuid NOT NULL, title text NOT NULL, state text NOT NULL DEFAULT 'open', acknowledged_by text, acknowledged_at timestamptz, opened_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolution text, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,monitor_id) REFERENCES monitors(workspace_id,id));
CREATE UNIQUE INDEX one_open_incident ON incidents(monitor_id) WHERE resolved_at IS NULL;
CREATE TABLE incident_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, incident_id uuid NOT NULL, kind text NOT NULL, message text NOT NULL, actor_id text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,incident_id) REFERENCES incidents(workspace_id,id));
CREATE TABLE maintenance_windows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, monitor_ids uuid[] NOT NULL DEFAULT '{}', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'UTC', recurrence text NOT NULL DEFAULT 'once', created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE TABLE alert_channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, type text NOT NULL, destination text NOT NULL, encrypted_credentials text, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE alert_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, config jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), channel_id uuid, incident_id uuid, event text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_token uuid, lease_until timestamptz, provider_id text, error_code text, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,channel_id) REFERENCES alert_channels(workspace_id,id), FOREIGN KEY(workspace_id,incident_id) REFERENCES incidents(workspace_id,id));
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','editor','viewer')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, cancelled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE status_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, slug text NOT NULL UNIQUE, published boolean NOT NULL DEFAULT false, password_hash text, config jsonb NOT NULL DEFAULT '{}', custom_domain text UNIQUE, domain_verified_at timestamptz, views bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE status_components (workspace_id uuid NOT NULL, page_id uuid NOT NULL, monitor_id uuid NOT NULL, position integer NOT NULL DEFAULT 0, PRIMARY KEY(page_id,monitor_id), FOREIGN KEY(workspace_id,page_id) REFERENCES status_pages(workspace_id,id), FOREIGN KEY(workspace_id,monitor_id) REFERENCES monitors(workspace_id,id));
CREATE TABLE status_subscribers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, page_id uuid NOT NULL, email text NOT NULL, token_hash text NOT NULL UNIQUE, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(page_id,email), FOREIGN KEY(workspace_id,page_id) REFERENCES status_pages(workspace_id,id));
CREATE TABLE status_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL, page_id uuid NOT NULL, title text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,page_id) REFERENCES status_pages(workspace_id,id));
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, token_hash text NOT NULL UNIQUE, prefix text NOT NULL, scopes text[] NOT NULL, expires_at timestamptz, revoked_at timestamptz, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), url text NOT NULL, encrypted_secret text NOT NULL, events text[] NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), actor_id text NOT NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id), provider_customer_id text UNIQUE, provider_subscription_id text UNIQUE, plan text NOT NULL DEFAULT 'free', state text NOT NULL DEFAULT 'free', current_period_end timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE billing_events (id text PRIMARY KEY, payload_hash text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_preferences (user_id text PRIMARY KEY REFERENCES auth_user(id) ON DELETE CASCADE, preferences jsonb NOT NULL DEFAULT '{}', phone text, phone_verified_at timestamptz);
CREATE TABLE probes (id text PRIMARY KEY, workspace_id uuid REFERENCES workspaces(id), region text NOT NULL, capabilities text[] NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), draining boolean NOT NULL DEFAULT false, enrollment_hash text);
CREATE TABLE feature_flags (key text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false, rollout integer NOT NULL DEFAULT 0 CHECK(rollout BETWEEN 0 AND 100), workspace_ids uuid[] NOT NULL DEFAULT '{}');
CREATE TABLE support_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id text NOT NULL REFERENCES auth_user(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), reason text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['monitors','check_results','incidents','incident_events','maintenance_windows','alert_channels','alert_policies','notification_outbox','invitations','status_pages','status_components','status_subscribers','status_updates','api_keys','webhooks','audit_events','subscriptions'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',table_name); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (workspace_id = nullif(current_setting(''app.workspace_id'',true),'''')::uuid) WITH CHECK (workspace_id = nullif(current_setting(''app.workspace_id'',true),'''')::uuid)',table_name); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO watchtower_app',table_name); END LOOP; END $$;
GRANT SELECT,INSERT,UPDATE,DELETE ON auth_user,auth_session,auth_account,auth_verification,"twoFactor",auth_rate_limit,user_preferences TO watchtower_app;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authorize_workspace(text,uuid),list_user_workspaces(text),create_user_workspace(text,uuid,text) TO watchtower_app;
REVOKE UPDATE,DELETE ON audit_events FROM watchtower_app;
-- The migration owner temporarily disables only membership RLS to backfill existing identity links.
ALTER TABLE memberships DISABLE ROW LEVEL SECURITY;
INSERT INTO workspace_access SELECT workspace_id,user_id,role FROM memberships ON CONFLICT DO NOTHING;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
